const MANUAL=window.APP_DATA,LEARN=window.LEARN_DATA,FIGHTS=window.FIGHT_DATA,GUIDED=window.GUIDED_DATA,SIDELINE=window.SIDELINE_DATA,ARMORY=window.ARMORY_DATA,main=document.getElementById('main');
document.addEventListener('click',event=>{
  const starterLink=event.target.closest('.starter-link');
  if(!starterLink)return;
  event.preventDefault();
  location.href='../';
});
let deferredInstall=null,waitingWorker=null,reloadForUpdate=false;
const PROGRESS_KEY='snd-lesson-progress-v330',MISSION_KEY='snd-active-mission-v330',HISTORY_KEY='snd-mission-history-v330',NOTES_KEY='snd-beginner-notes',FAVORITES_KEY='snd-favorites-v340',RECENTS_KEY='snd-recents-v340',SIDELINE_KEY='snd-sideline-patterns-v1';
const esc=(s='')=>String(s).replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]));
const slug=s=>String(s).toLowerCase().trim().replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'');
const readJSON=(key,fallback)=>{try{return JSON.parse(localStorage.getItem(key))??fallback}catch{return fallback}};
const saveJSON=(key,value)=>localStorage.setItem(key,JSON.stringify(value));
const toast=msg=>{const t=document.getElementById('toast');t.textContent=msg;t.style.display='block';clearTimeout(t._timer);t._timer=setTimeout(()=>t.style.display='none',1900)};
const terms=[...LEARN.terms];
(MANUAL.dictionary||[]).forEach(d=>{const id=slug(d.term);if(!terms.some(t=>t.id===id))terms.push({id,term:d.term,definition:d.definition})});
const termById=id=>terms.find(t=>t.id===decodeURIComponent(id))||terms.find(t=>slug(t.term)===decodeURIComponent(id));
const quickById=id=>LEARN.quick.find(x=>x.id===id),lessonById=id=>LEARN.lessons.find(x=>x.id===id),fightById=id=>FIGHTS.find(x=>x.id===id),missionById=id=>GUIDED.missions.find(x=>x.id===id),weaponById=id=>ARMORY.weapons.find(x=>x.id===decodeURIComponent(id));
function go(path){location.hash='#/'+path}
function route(){return location.hash.replace(/^#\/?/,'')||'home'}
function setNav(root){const mapped=['lesson','fights','fight','manual','operation','armory','weapon'].includes(root)?'learn':['guided','quick'].includes(root)?'round-read':root==='notes'?'practice':root;document.querySelectorAll('.nav').forEach(b=>{const active=b.dataset.root===mapped;b.classList.toggle('active',active);if(active)b.setAttribute('aria-current','page');else b.removeAttribute('aria-current')})}
function focusView(){const heading=main.querySelector('h1,h2');if(heading){heading.tabIndex=-1;heading.focus({preventScroll:true})}else main.focus({preventScroll:true})}
function shareButton(){return `<button class="sharebtn" data-share>Copy page link</button>`}
function bindShare(){const b=document.querySelector('[data-share]');if(b)b.onclick=async()=>{try{await navigator.clipboard.writeText(location.href);toast('Page link copied')}catch{prompt('Copy this link:',location.href)}}}
function bindGo(){document.querySelectorAll('[data-go]').forEach(button=>{button.onclick=event=>go(event.currentTarget.dataset.go)})}
function searchablePages(){
  return [
    ...LEARN.lessons.map(x=>({type:'Lesson',title:x.title,summary:x.subtitle,route:`lesson/${x.id}`,text:JSON.stringify(x)})),
    ...LEARN.quick.map(x=>({type:'Quick help',title:x.title,summary:x.short,route:`quick/${x.id}`,text:JSON.stringify(x)})),
    ...FIGHTS.map(x=>({type:'Fight correction',title:x.title,summary:x.cue,route:`fight/${x.id}`,text:JSON.stringify(x)})),
    ...MANUAL.operations.map(x=>({type:`Operation ${String(x.id).padStart(2,'0')}`,title:x.title,summary:x.try,route:`operation/${x.id}`,text:JSON.stringify(x)})),
    ...terms.map(x=>({type:'Game term',title:x.term,summary:x.definition,route:`term/${encodeURIComponent(x.id)}`,text:`${x.term} ${x.definition}`})),
    ...Object.entries(GUIDED.results).map(([id,x])=>({type:'Guided result',title:x.title,summary:x.action,route:`guided/result/${id}`,text:JSON.stringify(x)})),
    ...ARMORY.weapons.map(x=>({type:`Armory · ${x.category}`,title:x.name,summary:x.role,route:`weapon/${x.id}`,text:JSON.stringify(x)}))
  ];
}
function favorites(){return readJSON(FAVORITES_KEY,[]).filter(x=>x&&x.route)}
function recents(){return readJSON(RECENTS_KEY,[]).filter(x=>x&&x.route)}
function pageInfo(path=route()){return searchablePages().find(x=>x.route===path)}
function rememberPage(path=route()){const item=pageInfo(path);if(!item)return;saveJSON(RECENTS_KEY,[item,...recents().filter(x=>x.route!==item.route)].slice(0,8))}
function isFavorite(path=route()){return favorites().some(x=>x.route===path)}
function toggleFavorite(path=route()){const item=pageInfo(path);if(!item)return;const next=isFavorite(path)?favorites().filter(x=>x.route!==path):[item,...favorites().filter(x=>x.route!==path)];saveJSON(FAVORITES_KEY,next);enhanceDetailPage();toast(isFavorite(path)?'Page saved':'Removed from saved pages')}
function enhanceDetailPage(){const item=pageInfo();if(!item)return;rememberPage();document.querySelector('.page-tools')?.remove();const tools=document.createElement('div');tools.className='page-tools';tools.innerHTML=`<button class="secondary" id="favoritePage"><span class="saved-star">${isFavorite()?'★':'☆'}</span> ${isFavorite()?'Saved':'Save page'}</button><button class="ghost" data-go="library">Search guide</button>`;main.appendChild(tools);document.getElementById('favoritePage').onclick=()=>toggleFavorite();bindGo()}
function resultRows(items){return items.length?`<div class="button-list">${items.map(x=>`<button class="bigrow" data-go="${esc(x.route)}"><span class="search-result-type">${esc(x.type)}</span><strong>${esc(x.title)}</strong><small>${esc(x.summary||'')}</small></button>`).join('')}</div>`:`<div class="library-empty">Nothing here yet.</div>`}
function renderLibrary(){setNav('');const saved=favorites(),recent=recents();main.innerHTML=`<section class="hero"><span class="badge">FIND IT FAST</span><h1>Search the whole guide.</h1><p>Lessons, quick help, fight corrections, Field Manual operations, Guided results, game terms, and the firearm Armory are all in one place.</p></section><div class="library-tools"><input class="search" id="globalSearch" type="search" autocomplete="off" placeholder="Search timer, trade, Locus, bomb..." aria-label="Search the whole guide"><div id="globalResults"></div></div><div id="savedSections"><div class="section-label">Saved pages</div>${resultRows(saved)}<div class="section-label">Recently opened</div>${resultRows(recent)}</div>`;const input=document.getElementById('globalSearch'),results=document.getElementById('globalResults'),sections=document.getElementById('savedSections');input.oninput=()=>{const q=input.value.trim().toLowerCase();sections.hidden=!!q;if(!q){results.innerHTML='';return}const matches=searchablePages().filter(x=>(`${x.title} ${x.summary} ${x.text}`).toLowerCase().includes(q)).slice(0,30);results.innerHTML=`<div class="section-label">${matches.length} result${matches.length===1?'':'s'}</div>${resultRows(matches)}`;bindGo()};bindGo();setTimeout(()=>input.focus(),0);window.scrollTo(0,0)}
function termNote(ids=[]){const found=[...new Set(ids)].map(termById).filter(Boolean);if(!found.length)return'';return `<div class="term-note"><p><strong>Game terms on this page.</strong> Tap a term for its dictionary definition.</p><div class="term-chips">${found.map(t=>`<a class="term-chip" href="#/term/${encodeURIComponent(t.id)}">${esc(t.term)}</a>`).join('')}</div></div>`}
function termsInText(text=''){const s=text.toLowerCase();return terms.filter(t=>s.includes(t.term.toLowerCase())).slice(0,7).map(t=>t.id)}
function progress(){const p=readJSON(PROGRESS_KEY,{completed:[],last:null});p.completed=Array.isArray(p.completed)?p.completed:[];return p}
function setLastLesson(id){const p=progress();p.last=id;saveJSON(PROGRESS_KEY,p)}
function toggleLesson(id){const p=progress();p.completed=p.completed.includes(id)?p.completed.filter(x=>x!==id):[...p.completed,id];p.last=id;saveJSON(PROGRESS_KEY,p);renderLesson(id);toast(p.completed.includes(id)?'Lesson marked complete':'Lesson marked incomplete')}
function activeMission(){return readJSON(MISSION_KEY,null)}
function missionHistory(){return readJSON(HISTORY_KEY,[])}
function startMission(mission,source='Guide'){const m={id:mission.id,title:mission.title,short:mission.short||'',instruction:mission.instruction,cue:mission.cue||'',route:mission.route||'',source,rounds:0,successes:0,results:[],startedAt:new Date().toISOString()};saveJSON(MISSION_KEY,m);go('practice');toast('Practice mission started')}
function startMissionById(id,source='Guided diagnosis'){const m=missionById(id);if(m)startMission(m,source)}
function recordMission(ok){const m=activeMission();if(!m||m.rounds>=5)return;m.rounds++;if(ok)m.successes++;m.results.push(ok?'yes':'no');saveJSON(MISSION_KEY,m);renderPractice();if(m.rounds===5)toast(`Five rounds complete: ${m.successes}/5`)}
function finishMission(){const m=activeMission();if(!m)return;const note=document.getElementById('missionNote')?.value.trim()||'';const history=[{...m,note,completedAt:new Date().toISOString()},...missionHistory()].slice(0,12);saveJSON(HISTORY_KEY,history);localStorage.removeItem(MISSION_KEY);renderPractice();toast('Mission saved')}
function endMission(){localStorage.removeItem(MISSION_KEY);renderPractice();toast('Mission ended')}
function practiceButton(missionId,label='Start 5-round mission',source='Guide'){return `<button class="primary" data-mission="${esc(missionId)}" data-source="${esc(source)}">${esc(label)}</button>`}
function bindMissionButtons(){document.querySelectorAll('[data-mission]').forEach(b=>b.onclick=()=>startMissionById(b.dataset.mission,b.dataset.source||'Guide'));const dynamic=document.querySelector('[data-dynamic-mission]');if(dynamic)dynamic.onclick=()=>{const raw=JSON.parse(dynamic.dataset.dynamicMission);startMission(raw,dynamic.dataset.source||'Guide')}}
function dynamicMissionButton(m,source){return `<button class="primary" data-dynamic-mission='${esc(JSON.stringify(m))}' data-source="${esc(source)}">Start 5-round mission</button>`}
function renderProgressCard(){const p=progress(),total=LEARN.lessons.length,done=p.completed.filter(id=>lessonById(id)).length,next=LEARN.lessons.find(l=>!p.completed.includes(l.id)),last=lessonById(p.last),resume=last&&!p.completed.includes(last.id)?last:next;const pct=total?Math.round(done/total*100):0;return `<div class="progress-card"><div class="progress-head"><strong>Beginner lessons</strong><span>${done}/${total}</span></div><div class="progress-track" role="progressbar" aria-label="Beginner lesson progress" aria-valuemin="0" aria-valuemax="${total}" aria-valuenow="${done}" aria-valuetext="${done} of ${total} lessons complete"><div class="progress-fill" style="width:${pct}%"></div></div><small>${done===total?'All beginner lessons completed.':resume?`Next: ${esc(resume.title)}`:'Choose a lesson to begin.'}</small>${resume?`<div class="quick-actions"><button class="secondary" data-go="lesson/${resume.id}">Continue learning</button></div>`:''}</div>`}
function renderMissionSnapshot(){const m=activeMission();if(!m)return `<div class="card"><h3>No active practice mission</h3><p>Choose one small behavior to test for five rounds so the result is easier to judge.</p><button class="secondary" data-go="practice">Choose a mission</button></div>`;return `<div class="mission-card"><span class="badge yellow">ACTIVE MISSION</span><h3>${esc(m.title)}</h3><p>${esc(m.instruction)}</p><div class="round-dots">${[0,1,2,3,4].map(i=>`<div class="round-dot ${m.results[i]==='yes'?'yes':m.results[i]==='no'?'no':''}">${m.results[i]==='yes'?'✓':m.results[i]==='no'?'×':i+1}</div>`).join('')}</div><button class="primary" data-go="practice">Open practice tracker</button></div>`}
let currentSidelineResult=null;
function sidelinePatterns(){return readJSON(SIDELINE_KEY,[]).filter(x=>x&&x.ruleId&&x.check&&x.decision&&x.route).slice(0,8)}
function normalizeRoundText(value=''){return String(value).toLowerCase().replace(/[’]/g,"'").replace(/[^a-z0-9'\s-]/g,' ').replace(/\s+/g,' ').trim()}
function matchSidelineRule(value=''){const text=normalizeRoundText(value);return SIDELINE.rules.find(rule=>rule.keywords.some(keyword=>text.includes(keyword)))||SIDELINE.fallback}
function sidelineContext(){const map=document.getElementById('sidelineMap')?.value.trim()||'';const side=document.getElementById('sidelineSide')?.value||'';const objective=document.getElementById('sidelineObjective')?.value||'';return {map,side,objective}}
function contextMarkup(context){const items=[];if(context.map)items.push(`Map: ${context.map}`);if(context.side)items.push(`Side: ${context.side}`);if(context.objective)items.push(`Objective: ${context.objective}`);return items.length?`<div class="context-chips">${items.map(item=>`<span>${esc(item)}</span>`).join('')}</div>`:''}
function analyzeSidelineAccount(account,context){const rule=matchSidelineRule(account);return {ruleId:rule.id,account,context,missing:rule.missing,inference:rule.inference,decision:rule.decision,check:rule.check,route:rule.route,routeLabel:rule.routeLabel,terms:rule.terms}}
function savedPatternMarkup(){const saved=sidelinePatterns();if(!saved.length)return `<div class="saved-pattern-empty">No patterns saved. The round account above is never saved automatically.</div>`;return `<div class="saved-patterns">${saved.map((item,index)=>`<article class="saved-pattern"><div><span class="saved-pattern-number">${index+1}</span><strong>${esc(item.decision)}</strong><p>${esc(item.check)}</p><small>Saved locally ${new Date(item.savedAt).toLocaleDateString()}</small></div><div class="saved-pattern-actions"><button class="secondary" data-go="${esc(item.route)}">Open guide</button><button class="ghost danger" data-remove-pattern="${esc(item.id)}">Remove</button></div></article>`).join('')}</div>`}
function renderSidelineResult(result){currentSidelineResult=result;const resultNode=document.getElementById('sidelineResult');resultNode.innerHTML=`<section class="sideline-output" aria-labelledby="sidelineResultTitle"><h2 id="sidelineResultTitle">Round read</h2><div class="duo-grid"><article class="nerv-panel"><div class="brain-label"><span class="brain-mark nerv-mark" aria-hidden="true">N</span><div><strong>NERV</strong><small>Grounded observer</small></div></div><div class="evidence-block"><strong>Known from your account</strong><p>You reported: “${esc(result.account)}”</p>${contextMarkup(result.context)}</div><div class="evidence-block missing"><strong>Still missing</strong><p>${esc(result.missing)}</p></div><div class="evidence-block inference"><strong>Possible, not confirmed</strong><p>${esc(result.inference)}</p></div></article><article class="recon-panel"><div class="brain-label"><span class="brain-mark recon-mark" aria-hidden="true">R</span><div><strong>RECON</strong><small>Tactical continuity</small></div></div><div class="decision-block"><strong>One decision point</strong><p>${esc(result.decision)}</p></div><div class="next-check"><strong>One next-round check · beginner-safe default</strong><p>${esc(result.check)}</p></div><div class="quick-actions"><button class="primary" data-go="${esc(result.route)}">${esc(result.routeLabel)}</button><button class="secondary" id="saveSidelinePattern">Save this pattern locally</button></div></article></div>${termNote(result.terms)}<p class="privacy-line">This result came from local rule matching. It did not inspect the game, use a screenshot, contact an AI service, or save your typed account.</p></section>`;bindGo();document.getElementById('saveSidelinePattern').onclick=saveSidelinePattern;resultNode.scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth',block:'start'});document.getElementById('sidelineResultTitle').tabIndex=-1;document.getElementById('sidelineResultTitle').focus({preventScroll:true})}
function saveSidelinePattern(){if(!currentSidelineResult)return;const result=currentSidelineResult;const item={id:`${Date.now()}-${result.ruleId}`,ruleId:result.ruleId,decision:result.decision,check:result.check,route:result.route,savedAt:new Date().toISOString()};saveJSON(SIDELINE_KEY,[item,...sidelinePatterns().filter(x=>x.ruleId!==item.ruleId)].slice(0,8));document.getElementById('savedPatternList').innerHTML=savedPatternMarkup();bindSidelineSaved();toast('Pattern saved on this device')}
function bindSidelineSaved(){bindGo();document.querySelectorAll('[data-remove-pattern]').forEach(button=>button.onclick=()=>{saveJSON(SIDELINE_KEY,sidelinePatterns().filter(item=>item.id!==button.dataset.removePattern));document.getElementById('savedPatternList').innerHTML=savedPatternMarkup();bindSidelineSaved();toast('Saved pattern removed')})}
function bindSideline(){const input=document.getElementById('roundAccount'),form=document.getElementById('sidelineForm'),hint=document.getElementById('sidelineHint');document.querySelectorAll('[data-sideline-example]').forEach(button=>button.onclick=()=>{input.value=button.dataset.sidelineExample;input.focus()});form.onsubmit=event=>{event.preventDefault();const account=input.value.trim();if(account.length<3){hint.textContent='Start with one outside cue: what did you see or hear immediately before the round changed?';input.focus();return}hint.textContent='';renderSidelineResult(analyzeSidelineAccount(account,sidelineContext()))};bindSidelineSaved()}
function renderSideline(){setNav('round-read');currentSidelineResult=null;main.innerHTML=`<section class="hero sideline-hero"><span class="badge">BACKROOM ROUND READ</span><h1>What happened?</h1><p>A fragment is enough. NERV separates the report from uncertainty. RECON returns one decision point and one check for the next round.</p><div class="hero-proof"><span>Local rule matching</span><span>No screen access</span><span>No automatic saving</span></div></section><form id="sidelineForm" class="sideline-form"><label for="roundAccount"><strong>Round account</strong><small>Use your own words. It does not need to be complete.</small></label><textarea id="roundAccount" class="notearea round-account" maxlength="600" autocomplete="off" placeholder="Example: I rushed because I thought my teammate had that angle"></textarea><div class="example-fragments" aria-label="Example round fragments">${SIDELINE.examples.map(example=>`<button type="button" class="fragment" data-sideline-example="${esc(example)}">${esc(example)}</button>`).join('')}</div><details class="context-details"><summary>Add optional context</summary><div class="context-grid"><label for="sidelineMap">Map or landmark<input id="sidelineMap" type="text" maxlength="60" autocomplete="off" placeholder="Example: Raid, near pool"></label><label for="sidelineSide">Side<select id="sidelineSide"><option value="">Not given</option><option>Attacking</option><option>Defending</option></select></label><label for="sidelineObjective">Objective state<select id="sidelineObjective"><option value="">Not given</option><option>Bomb not planted</option><option>Our bomb planted</option><option>Enemy bomb planted</option><option>Site unclear</option></select></label></div></details><p id="sidelineHint" class="form-hint" role="status" aria-live="polite"></p><button class="primary sideline-submit" type="submit">Read this round</button></form><div id="sidelineResult" aria-live="polite"></div><section class="sideline-secondary"><div class="section-label">Prefer fixed choices?</div><button class="bigrow" data-go="guided"><strong>Open the original Guided review</strong><small>Use a two- or three-question decision tree instead of typing.</small></button><div class="section-label">Optional local continuity</div><div id="savedPatternList">${savedPatternMarkup()}</div></section><div class="privacy-card"><strong>Capability boundary</strong><p>This first version reads only the text and optional context entered on this page. It cannot see the match, capture the screen, analyze a screenshot or clip, control the game, or contact an outside AI provider.</p></div>`;bindGo();bindSideline();window.scrollTo(0,0)}
function renderHome(){setNav('home');main.innerHTML=`<section class="hero"><span class="badge">THE BACKROOM</span><h1>Here is why that shit worked. Or why it absolutely did not.</h1><p>Use this when you want the logic behind a Field Order: the round state, likely information, geometry, timing, trade options, exceptions, and what is still only a hypothesis.</p></section><a class="bigrow starter-link" href="../"><strong>Just tell me what to do.</strong><small>Open Field Orders for the fast version: one useful action at a time, with none of the research homework in your face.</small></a><button class="bigrow sideline-launch" data-go="round-read"><strong>Bring a confusing round to the Backroom.</strong><small>NERV keeps the account grounded. RECON returns one decision point and one observable next-round check.</small></button>${renderProgressCard()}${renderMissionSnapshot()}<div class="path"><button class="path-step" data-go="round-read"><b>1</b><strong>What actually went wrong?</strong><small>Separate what was reported from what is missing or only possible.</small></button><button class="path-step" data-go="learn"><b>2</b><strong>Show me the receipts</strong><small>Open the concepts, decisions, terms, and exceptions behind the orders.</small></button><button class="path-step" data-go="practice"><b>3</b><strong>Test one correction</strong><small>Track five rounds instead of pretending one good round proves anything.</small></button></div><div class="section-label">Fast access</div><div class="button-list two"><button class="bigrow" data-go="lesson/orientation"><strong>I lose track of A and B</strong><small>Use objective markers and visible landmarks.</small></button><button class="bigrow" data-go="quick/our-bomb-planted"><strong>We planted the bomb</strong><small>Use positions, sound, and the timer.</small></button><button class="bigrow" data-go="quick/enemy-bomb-planted"><strong>The enemy planted</strong><small>Check time, group, clear, and protect the defuse.</small></button><button class="bigrow" data-go="terms"><strong>I heard a term I do not know</strong><small>Open the game-term dictionary.</small></button></div>`;bindGo();window.scrollTo(0,0)}
function renderGuidedStart(){setNav('guided');const q=GUIDED.questions.start;main.innerHTML=`<section class="hero"><span class="badge">GUIDED ROUND REVIEW</span><h1>Turn a confusing round into one useful correction.</h1><p>No score judgment. No random teammate screaming. Just enough questions to identify the most likely problem.</p></section>${questionMarkup('start',q,1)}`;bindGuided();window.scrollTo(0,0)}
function questionMarkup(id,q,step){return `<section class="question-card"><div class="question-count">Step ${step}</div><h1>${esc(q.prompt)}</h1><p>${esc(q.help||'')}</p></section><div class="choice-grid">${q.options.map(o=>`<button class="choice" data-next="${esc(o.next||'')}" data-result="${esc(o.result||'')}"><strong>${esc(o.label)}</strong>${o.detail?`<small>${esc(o.detail)}</small>`:''}</button>`).join('')}</div>${q.back?`<div class="quick-actions"><button class="ghost" data-go="guided/q/${q.back}">← Previous question</button><button class="ghost" data-go="guided">Start over</button></div>`:''}`}
