function bindGuided(){document.querySelectorAll('[data-next],[data-result]').forEach(b=>b.onclick=()=>{if(b.dataset.result)go(`guided/result/${b.dataset.result}`);else if(b.dataset.next)go(`guided/q/${b.dataset.next}`)})}
function renderGuidedResult(id){const r=GUIDED.results[id];if(!r)return go('guided');setNav('guided');const links=[r.lesson?`<button class="secondary" data-go="lesson/${r.lesson}">Open related lesson</button>`:'',r.fight?`<button class="secondary" data-go="fight/${r.fight}">Open fight correction</button>`:'',r.operation?`<button class="secondary" data-go="operation/${r.operation}">Open Field Manual operation</button>`:''].join('');main.innerHTML=`<button class="ghost" data-go="guided">← Start another review</button><section class="hero"><span class="badge">LIKELY EXPLANATION</span><h1>${esc(r.title)}</h1></section><div class="now"><strong>Try this next round</strong><span>${esc(r.action)}</span></div><div class="result-grid"><div class="result-box"><strong>What likely happened</strong>${esc(r.likely)}</div><div class="result-box"><strong>Why the correction helps</strong>${esc(r.why)}</div></div>${termNote(r.terms)}<div class="mission-card"><span class="badge yellow">PRACTICE IT</span><h3>${esc(missionById(r.mission)?.title||'Five-round mission')}</h3><p>${esc(missionById(r.mission)?.instruction||'Practice this correction for five rounds.')}</p><div class="quick-actions">${practiceButton(r.mission,'Start this mission','Guided diagnosis')}</div></div><div class="quick-actions">${links}${shareButton()}</div>`;bindGo();bindShare();bindMissionButtons();window.scrollTo(0,0)}
function renderQuickList(){setNav('guided');main.innerHTML=`<button class="ghost" data-go="guided">← Guided help</button><section class="hero"><span class="badge">DIRECT MID-MATCH HELP</span><h2>What is happening right now?</h2><p>Skip the diagnosis and open the closest situation.</p></section><div class="button-list">${LEARN.quick.map(q=>`<button class="bigrow" data-go="quick/${q.id}"><strong>${esc(q.title)}</strong><small>${esc(q.short)}</small></button>`).join('')}</div>`;bindGo();window.scrollTo(0,0)}
function renderQuick(id){const q=quickById(id);if(!q)return go('quick');setNav('guided');main.innerHTML=`<button class="ghost" data-go="quick">← All situations</button><section class="hero"><span class="badge">QUICK HELP</span><h1>${esc(q.title)}</h1><p>${esc(q.short)}</p></section><div class="now"><strong>Do this now</strong><span>${esc(q.action)}</span></div><div class="card"><h3>Four steps</h3><div class="steps">${q.steps.map(x=>`<div class="step">${esc(x)}</div>`).join('')}</div></div><div class="card"><h3>Why this works</h3><p>${esc(q.why)}</p></div>${termNote(q.terms)}<div class="quick-actions">${shareButton()}<button class="ghost" data-go="guided">Open guided review</button></div>`;bindGo();bindShare();window.scrollTo(0,0)}
function renderLearn(){setNav('learn');const p=progress();main.innerHTML=`<section class="hero"><span class="badge">LEARN THE MODE</span><h2>The parts beginners should not have to discover through avoidable mistakes.</h2><p>Read in order or open the exact subject that keeps costing rounds.</p></section>${renderProgressCard()}<div class="button-list">${LEARN.lessons.map((l,i)=>`<button class="bigrow" data-go="lesson/${l.id}"><strong>${p.completed.includes(l.id)?'✓ ':''}${i+1}. ${esc(l.title)}</strong><small>${esc(l.subtitle)}</small></button>`).join('')}</div><div class="section-label">Builds and armory</div><button class="bigrow armory-entry" data-go="armory"><span class="search-result-type">${ARMORY.weapons.length} firearms</span><strong>Open the Backroom Armory</strong><small>Search one five-part starting build for every current firearm, with its S&amp;D job, tradeoff, source, and live-verification warning.</small></button><div class="section-label">Individual fights</div><button class="bigrow" data-go="fights"><strong>Winning Fights</strong><small>Ten repeated fight problems with one correction and one practice mission.</small></button><div class="section-label">Deeper practice</div><button class="bigrow" data-go="manual"><strong>Open the 30-operation Field Manual</strong><small>Problem-based lessons for decisions, awareness, bomb play, and improvement.</small></button>`;bindGo();window.scrollTo(0,0)}
function armorySourceLabel(w){return w.sourceKind.includes('Archived')?'Open archived build source':w.source.includes('reddit.com')?'Open community discussion':'Open build source'}
const armoryRole=id=>ARMORY.meta.roles?.[id];
function armoryDeepCard(w){return `<button class="armory-row" data-go="weapon/${esc(w.id)}"><span class="weapon-class">${esc(w.category)}</span><strong>${esc(w.name)}</strong><small>${esc(w.role)} · ${w.displayStats?.base&&Object.keys(w.displayStats.base).length?'displayed ratings included':'attachment analysis included'}</small></button>`}
function renderArmoryDeep(initialRole='All'){setNav('armory');const categories=['All',...new Set(ARMORY.weapons.map(x=>x.category))],roles=[['All','Every role'],...Object.entries(ARMORY.meta.roles||{}).filter(([id])=>id!=='backup').map(([id,x])=>[id,x.label])];let activeCategory='All',activeRole=armoryRole(initialRole)?initialRole:'All';const role=armoryRole(activeRole),roleCount=activeRole==='All'?ARMORY.weapons.length:ARMORY.weapons.filter(w=>w.roleId===activeRole).length;main.innerHTML=`<button class="ghost" data-go="${role?'armory':'learn'}">← ${role?'All firearms':'Learn'}</button><section class="hero armory-hero ${role?'role-view':''}"><span class="badge">BACKROOM ARMORY</span><h1>${role?esc(role.label)+' weapons':'A full S&amp;D dossier for every firearm.'}</h1><p>${role?esc(role.cue):'Search the entire firearm catalog, group it by the job it serves, then open the attachment reasoning, handling tradeoffs, finger-layout fit, and displayed weapon ratings when the source exposes them.'}</p><div class="armory-count"><b>${roleCount}</b><span>${role?'weapons in this job':'firearms covered'}</span></div></section><div class="card armory-boundary"><h3>How these recommendations were built</h3><p>The recommended five parts combine current displayed weapon ratings and attachment effects where available with mobile S&amp;D judgment: ready speed, recoil conversion, concealment, magazine burden, sight picture, and the range where the role actually fights. Displayed ratings are comparative menu-style numbers—not physical damage, RPM, aim time, or time-to-kill measurements.</p></div><label class="armory-search-label" for="armorySearch">Find a firearm</label><input class="search" id="armorySearch" type="search" autocomplete="off" placeholder="Search Locus, M4, close route..." aria-label="Search the armory"><div class="section-label">Filter by job</div><div class="armory-filters role-filters" role="group" aria-label="Filter by weapon job">${roles.map(([id,label])=>`<button class="armory-filter ${id===activeRole?'active':''}" data-role="${esc(id)}" aria-pressed="${id===activeRole}">${esc(label)}</button>`).join('')}</div><div class="section-label">Filter by firearm class</div><div class="armory-filters" role="group" aria-label="Filter by weapon class">${categories.map((x,i)=>`<button class="armory-filter ${i===0?'active':''}" data-category="${esc(x)}" aria-pressed="${i===0}">${esc(x)}</button>`).join('')}</div><div class="armory-result-head"><strong id="armoryResultCount"></strong><small>Tap one for the complete S&amp;D dossier.</small></div><div class="armory-list" id="armoryList"></div><div class="card"><h3>Live-game check</h3><p>Balance and attachment behavior can change. Confirm the exact five names and effect descriptions in Global Multiplayer Gunsmith. If the live game disagrees, the live game wins.</p><p class="armory-reviewed">Catalog checked ${esc(ARMORY.meta.checked)}.</p></div>`;const input=document.getElementById('armorySearch'),list=document.getElementById('armoryList'),count=document.getElementById('armoryResultCount');const update=()=>{const q=input.value.trim().toLowerCase();const matches=ARMORY.weapons.filter(w=>(activeCategory==='All'||w.category===activeCategory)&&(activeRole==='All'||w.roleId===activeRole)&&(`${w.name} ${w.category} ${w.role} ${w.cue} ${w.attachments.join(' ')}`).toLowerCase().includes(q));list.innerHTML=matches.length?matches.map(armoryDeepCard).join(''):`<div class="library-empty">No firearm matches those filters.</div>`;count.textContent=`${matches.length} firearm${matches.length===1?'':'s'}`;bindGo()};input.oninput=update;document.querySelectorAll('[data-category]').forEach(button=>button.onclick=()=>{activeCategory=button.dataset.category;document.querySelectorAll('[data-category]').forEach(x=>{const on=x===button;x.classList.toggle('active',on);x.setAttribute('aria-pressed',String(on))});update()});document.querySelectorAll('[data-role]').forEach(button=>button.onclick=()=>{activeRole=button.dataset.role;document.querySelectorAll('[data-role]').forEach(x=>{const on=x===button;x.classList.toggle('active',on);x.setAttribute('aria-pressed',String(on))});update()});update();bindGo();window.scrollTo(0,0)}
function statPanel(w){const rows=w.statDeltas||[];if(!rows.length)return `<div class="card stat-boundary"><h3>Displayed rating panel</h3><p>The linked page did not expose a reliable base-to-build rating table for this firearm. No numbers are invented to fill the gap.</p></div>`;return `<section class="weapon-stats" aria-labelledby="ratingTitle"><h2 id="ratingTitle">Displayed rating change</h2><p>These comparative menu-style ratings help show the direction of the build. They are not damage, RPM, milliseconds, or TTK.</p><div class="stat-rows">${rows.map(s=>`<div class="stat-row"><b>${esc(s.label)}</b><span>${s.base} → ${s.built}</span><em class="${s.delta>0?'up':s.delta<0?'down':''}">${s.delta>0?'+':''}${s.delta}</em></div>`).join('')}</div></section>`}
function renderWeaponDeep(id){const w=weaponById(id);if(!w)return go('armory');setNav('weapon');const visibleLaser=w.attachments.some(x=>/laser/i.test(x)),role=armoryRole(w.roleId),related=ARMORY.weapons.filter(x=>x.roleId===w.roleId&&x.id!==w.id).slice(0,8);const buildText=[w.name,...w.attachments.map((x,i)=>`${i+1}. ${x}`),`Secondary: ${w.loadout.secondary}`,`Perks: ${w.loadout.perks.join(' / ')}`,`Equipment: ${w.loadout.lethal} / ${w.loadout.tactical}`].join('\n');main.innerHTML=`<button class="ghost" data-go="armory/role/${esc(w.roleId)}">← ${esc(w.role)}</button><section class="hero weapon-hero"><span class="badge">${esc(w.category)}</span><h1>${esc(w.name)}</h1><p>${esc(w.role)}</p></section><div class="now"><strong>Use it for this job</strong><span>${esc(w.cue)}</span></div><section class="weapon-build dossier-block" aria-labelledby="weaponBuildTitle"><div class="weapon-build-heading"><div><span class="search-result-type">RECOMMENDED MOBILE S&amp;D BUILD</span><h2 id="weaponBuildTitle">Five-part Gunsmith</h2></div><button class="secondary" id="copyWeaponBuild">Copy full loadout</button></div><p class="build-verdict">${esc(w.whyBuild)}</p><ol class="attachment-list armory-attachments reasoned-attachments">${w.attachments.map((a,i)=>`<li><div><strong>${esc(a)}</strong><span>${esc(w.attachmentReasons[i])}</span></div></li>`).join('')}</ol></section>${statPanel(w)}<section class="card dossier-block"><h3>Complete class around the firearm</h3><div class="loadout-grid"><div><b>Secondary</b><span>${esc(w.loadout.secondary)}</span></div><div><b>Perks</b><span>${w.loadout.perks.map(esc).join(' · ')}</span></div><div><b>Lethal</b><span>${esc(w.loadout.lethal)}</span></div><div><b>Tactical</b><span>${esc(w.loadout.tactical)}</span></div></div></section><section class="card dossier-block"><h3>How it fits fingers on a phone</h3><p>${esc(w.fingerFit)}</p></section><section class="card dossier-block"><h3>Tradeoffs to accept</h3><ul class="tradeoff-list">${w.tradeoffs.map(x=>`<li>${esc(x)}</li>`).join('')}</ul></section>${visibleLaser?`<div class="card laser-card"><h3>Visible laser check</h3><p>This setup contains a laser. If its live description says the beam is visible, keep it off a doorway or wall edge until the fight begins.</p></div>`:''}<div class="card recommendation-boundary"><h3>What “recommended” means here</h3><p><b>Our judgment:</b> this is the strongest practical S&amp;D combination we can justify from the available displayed ratings, attachment behavior, weapon role, and mobile control demands.</p><p><b>Not claimed:</b> it is not an exhaustive frame-data simulation, and a specialized team plan can justify another tradeoff.</p></div><section class="card"><h3>Other firearms for ${esc(w.role)}</h3><div class="related-weapons">${related.map(x=>`<button class="term-chip" data-go="weapon/${esc(x.id)}">${esc(x.name)}</button>`).join('')}</div><button class="secondary role-all" data-go="armory/role/${esc(w.roleId)}">See the full role group</button></section><div class="armory-source-card"><span class="source-kind">${esc(w.sourceKind)}</span><p>Source checked ${esc(w.checked)}. Confirm the exact parts and effect descriptions in the current Global Multiplayer Gunsmith.</p><a href="${esc(w.source)}" target="_blank" rel="noopener">${armorySourceLabel(w)}</a></div><div class="quick-actions">${shareButton()}<button class="ghost" data-go="armory">Search another firearm</button></div>`;document.getElementById('copyWeaponBuild').onclick=async()=>{try{await navigator.clipboard.writeText(buildText);toast('Full loadout copied')}catch{prompt('Copy this loadout:',buildText)}};bindGo();bindShare();window.scrollTo(0,0)}
function renderLesson(id){const l=lessonById(id);if(!l)return go('learn');setLastLesson(id);const p=progress(),done=p.completed.includes(id);setNav('learn');main.innerHTML=`<button class="ghost" data-go="learn">← All lessons</button><section class="hero"><span class="badge">BEGINNER LESSON</span><h1>${esc(l.title)}</h1><p>${esc(l.subtitle)}</p></section><div class="lesson-status"><strong>${done?'<span class="check">✓ Completed</span>':'Not completed yet'}</strong><button class="${done?'ghost':'primary'}" id="lessonComplete">${done?'Mark incomplete':'Mark lesson complete'}</button></div><div class="now"><strong>Main idea</strong><span>${esc(l.takeaway)}</span></div>${l.sections.map(s=>`<section class="lesson-section"><h3>${esc(s[0])}</h3><p>${esc(s[1])}</p></section>`).join('')}<div class="card"><h3>Common mistakes</h3><ul class="mistakes">${l.mistakes.map(x=>`<li>${esc(x)}</li>`).join('')}</ul></div>${termNote(l.terms)}<div class="quick-actions">${shareButton()}<button class="ghost" data-go="guided">Open guided help</button></div>`;document.getElementById('lessonComplete').onclick=()=>toggleLesson(id);bindGo();bindShare();window.scrollTo(0,0)}
function renderFights(){setNav('learn');main.innerHTML=`<button class="ghost" data-go="learn">← Learn</button><section class="hero"><span class="badge">WINNING FIGHTS</span><h2>Which repeated fight problem sounds familiar?</h2><p>The common game term is preserved and explained instead of being used as an entrance exam.</p></section><div class="button-list">${FIGHTS.map(f=>`<button class="bigrow" data-go="fight/${f.id}"><strong>${esc(f.trigger)}</strong><small>Game term: ${esc(f.term)} · ${esc(f.cue)}</small></button>`).join('')}</div>`;bindGo();window.scrollTo(0,0)}
function renderFight(id){const f=fightById(id);if(!f)return go('fights');setNav('learn');const dm={id:`fight-${f.id}`,title:f.title,short:f.cue,instruction:f.mission,cue:f.cue,route:`fight/${f.id}`};main.innerHTML=`<button class="ghost" data-go="fights">← Winning Fights</button><section class="hero"><span class="badge">FIGHT CORRECTION</span><h1>${esc(f.title)}</h1><p>${esc(f.summary)}</p></section><div class="now"><strong>Remember this during the round</strong><span>${esc(f.cue)}</span></div>${termNote([slug(f.term)])}<div class="compare"><div class="bad"><strong>What went wrong</strong>${esc(f.summary)}</div><div class="good"><strong>Better choice</strong>${esc(f.correction)}</div></div><div class="card"><h3>Four-step correction</h3><div class="steps">${f.steps.map(x=>`<div class="step">${esc(x)}</div>`).join('')}</div></div><div class="mission-card"><span class="badge yellow">FIVE-ROUND PRACTICE</span><h3>${esc(f.mission)}</h3><div class="quick-actions">${dynamicMissionButton(dm,'Winning Fights')}</div></div><div class="quick-actions">${shareButton()}<button class="ghost" data-go="manual">Related Field Manual</button></div>`;bindGo();bindShare();bindMissionButtons();window.scrollTo(0,0)}
function manualRow(o){return `<button class="bigrow" data-go="operation/${o.id}"><strong>${esc(o.title)}</strong><small>Operation ${String(o.id).padStart(2,'0')} · ${esc(o.mission)}</small></button>`}
function renderManual(){setNav('learn');main.innerHTML=`<button class="ghost" data-go="learn">← Learn</button><section class="hero"><span class="badge">FIELD MANUAL</span><h2>Thirty deeper problem-based lessons</h2><p>Use this when the same mistake keeps returning and a quick sentence is no longer enough.</p></section><input class="search" id="manualSearch" placeholder="Search dying early, bomb, timer, sound, cover..."><div class="manual-list" id="manualList">${MANUAL.operations.map(manualRow).join('')}</div>`;bindGo();document.getElementById('manualSearch').oninput=e=>{const q=e.target.value.toLowerCase();document.getElementById('manualList').innerHTML=MANUAL.operations.filter(o=>JSON.stringify(o).toLowerCase().includes(q)).map(manualRow).join('');bindGo()};window.scrollTo(0,0)}
function renderOperation(id){const o=MANUAL.operations.find(x=>x.id===Number(id));if(!o)return go('manual');setNav('learn');const text=[o.title,o.problem,o.truth,o.try,o.mission,o.success].join(' '),dm={id:`operation-${o.id}`,title:o.title,short:o.mission,instruction:o.mission,cue:o.try,route:`operation/${o.id}`};main.innerHTML=`<button class="ghost" data-go="manual">← Field Manual</button><section class="hero"><span class="badge">OPERATION ${String(o.id).padStart(2,'0')}</span><h1>${esc(o.title)}</h1></section><div class="now"><strong>One thing to try</strong><span>${esc(o.try)}</span></div><div class="card"><h3>The problem</h3><p>${esc(o.problem)}</p></div><div class="card"><h3>Why it happens</h3><p>${esc(o.truth)}</p></div><div class="mission-card"><span class="badge yellow">PRACTICE MISSION</span><h3>${esc(o.mission)}</h3><div class="quick-actions">${dynamicMissionButton(dm,'Field Manual')}</div></div><div class="card"><h3>Success looks like</h3><p>${esc(o.success)}</p></div>${termNote(termsInText(text))}<div class="quick-actions">${shareButton()}</div>`;bindGo();bindShare();bindMissionButtons();window.scrollTo(0,0)}
function renderPractice(){setNav('practice');const m=activeMission(),history=missionHistory();if(!m){main.innerHTML=`<section class="hero"><span class="badge">PRACTICE MISSIONS</span><h1>Fix one behavior for five rounds.</h1><p>Choose one mission, record whether you remembered it, and keep one short note. Limiting the test to one behavior makes the result easier to understand.</p></section><div class="section-label">Recommended missions</div><div class="button-list">${GUIDED.missions.slice(0,12).map(x=>`<button class="bigrow" data-mission="${x.id}" data-source="Practice list"><strong>${esc(x.title)}</strong><small>${esc(x.short)}</small></button>`).join('')}</div><div class="section-label">Field notes</div><button class="bigrow" data-go="notes"><strong>Open field notes</strong><small>Record one useful observation after a round or match.</small></button>${historyMarkup(history)}`;bindGo();bindMissionButtons();window.scrollTo(0,0);return}const completed=m.rounds>=5;main.innerHTML=`<section class="hero"><span class="badge">ACTIVE PRACTICE</span><h1>${esc(m.title)}</h1><p>${esc(m.source)} · ${m.rounds}/5 rounds recorded</p></section><div class="mission-card"><p>${esc(m.instruction)}</p>${m.cue?`<div class="mission-cue">${esc(m.cue)}</div>`:''}<div class="round-dots">${[0,1,2,3,4].map(i=>`<div class="round-dot ${m.results[i]==='yes'?'yes':m.results[i]==='no'?'no':''}">${m.results[i]==='yes'?'✓':m.results[i]==='no'?'×':i+1}</div>`).join('')}</div><div class="stat-grid"><div class="stat"><b>${m.rounds}</b><span>Rounds</span></div><div class="stat"><b>${m.successes}</b><span>Remembered</span></div><div class="stat"><b>${m.rounds-m.successes}</b><span>Missed</span></div></div>${completed?`<h3>Five rounds complete</h3><textarea class="notearea" id="missionNote" placeholder="One useful note: What changed? What stayed difficult?"></textarea><div class="quick-actions"><button class="primary" id="finishMission">Save and finish</button><button class="ghost" id="repeatMission">Repeat mission</button></div>`:`<div class="quick-actions"><button class="primary" id="missionYes">Remembered it</button><button class="ghost" id="missionNo">Missed it</button></div>`}<div class="quick-actions">${m.route?`<button class="secondary" data-go="${esc(m.route)}">Open related guide</button>`:''}<button class="ghost danger" id="endMission">End mission</button></div></div>${historyMarkup(history)}`;bindGo();if(!completed){document.getElementById('missionYes').onclick=()=>recordMission(true);document.getElementById('missionNo').onclick=()=>recordMission(false)}else{document.getElementById('finishMission').onclick=finishMission;document.getElementById('repeatMission').onclick=()=>{const again={...m,rounds:0,successes:0,results:[],startedAt:new Date().toISOString()};saveJSON(MISSION_KEY,again);renderPractice()}}document.getElementById('endMission').onclick=endMission;window.scrollTo(0,0)}
function historyMarkup(history){if(!history.length)return'';return `<div class="section-label">Recent practice</div><div class="history-list">${history.slice(0,5).map(h=>`<div class="history-row"><strong>${esc(h.title)} · ${h.successes}/5</strong><small>${esc(h.note||'No note saved.')}</small></div>`).join('')}</div>`}
function renderTerms(){setNav('terms');main.innerHTML=`<section class="hero"><span class="badge">GAME-TERM DICTIONARY</span><h2>Learn the language without already needing to know it.</h2><p>Established in-game and S&amp;D terminology stays. Disposable social-media slang does not get to charge admission.</p></section><input class="search" id="termSearch" placeholder="Search trade, re-peek, plant, rotation..."><div class="term-list" id="termList">${[...terms].sort((a,b)=>a.term.localeCompare(b.term)).map(termRow).join('')}</div>`;bindGo();document.getElementById('termSearch').oninput=e=>{const q=e.target.value.toLowerCase();document.getElementById('termList').innerHTML=terms.filter(t=>(t.term+' '+t.definition).toLowerCase().includes(q)).map(termRow).join('');bindGo()};window.scrollTo(0,0)}
function termRow(t){return `<button class="term-row" data-go="term/${encodeURIComponent(t.id)}"><strong>${esc(t.term)}</strong><small>${esc(t.definition)}</small></button>`}
function renderTerm(id){const t=termById(id);if(!t)return go('terms');setNav('terms');main.innerHTML=`<button class="ghost" data-go="terms">← Dictionary</button><section class="hero"><span class="badge">GAME TERM</span><h1>${esc(t.term)}</h1><p>${esc(t.definition)}</p></section><div class="card accent"><h3>Why the dictionary exists</h3><p>The guide keeps real game terminology so players can understand teammates, videos, and competitive discussion. Every term should be learnable without already belonging to the club.</p></div><div class="quick-actions">${shareButton()}</div>`;bindGo();bindShare();window.scrollTo(0,0)}
function renderNotes(){setNav('practice');const saved=localStorage.getItem(NOTES_KEY)||'';main.innerHTML=`<button class="ghost" data-go="practice">← Practice</button><section class="hero"><span class="badge">FIELD NOTES</span><h2>Turn one mistake into one replacement action.</h2><p>Notes are stored only on this device.</p></section><textarea id="notes" class="notearea" placeholder="Example:\nI died crossing while sprinting. Next match I will stop at cover and pre-aim before crossing.\n\nNew term: trade = staying close enough to respond after a teammate is eliminated."></textarea><div class="quick-actions"><button class="primary" id="saveNotes">Save notes</button><button class="ghost" id="clearNotes">Clear</button></div><div class="card"><h3>Four useful review questions</h3><div class="steps"><div class="step">What did I know before moving?</div><div class="step">What directions could see me?</div><div class="step">What did the bomb and timer require?</div><div class="step">What one action will I change next round?</div></div></div>`;document.getElementById('notes').value=saved;document.getElementById('saveNotes').onclick=()=>{localStorage.setItem(NOTES_KEY,document.getElementById('notes').value);toast('Field notes saved')};document.getElementById('clearNotes').onclick=()=>{document.getElementById('notes').value='';localStorage.removeItem(NOTES_KEY);toast('Notes cleared')};bindGo();window.scrollTo(0,0)}
function renderAbout(){setNav('');main.innerHTML=`<button class="ghost" data-go="home">← Start</button><section class="hero"><span class="badge">VERSION 3.9.0</span><h1>A beginner-first Search &amp; Destroy companion</h1><p>Created by Michael Barnes to help players learn the mode without depending on trial, error, and abuse from strangers.</p></section><div class="card"><h3>What changed in 3.9.0</h3><p>Expanded the Starter Guides tab into five approachable early-account loadouts and added the searchable Backroom Armory: a sourced starting configuration for every current firearm, with role cues and live-verification warnings.</p></div><div class="card"><h3>How the round read works</h3><p>NERV reports only what the player entered, what is still missing, and what remains a possible inference. RECON applies a transparent local rule to return one decision point and one observable check. They support the Backroom experience; they are not a separate product or a live game-reading service.</p></div><div class="card"><h3>Build evidence rule</h3><p>The Armory separates a complete sourced baseline from an official recommendation or a current-meta claim. Exact attachments must still be confirmed in the live Global Multiplayer Gunsmith.</p></div><div class="card"><h3>Language rule</h3><p>Use ordinary language first. Keep established game terminology, define it in the dictionary, and point readers toward that definition when it appears.</p></div><div class="card"><h3>Privacy</h3><p>Lesson progress, saved pages, recent pages, practice results, history, field notes, and explicitly saved round patterns remain on this device. Round accounts are not saved automatically, and saved patterns do not contain the original typed account.</p></div><div class="card"><h3>Unofficial project</h3><p>This is a fan-made learning guide. It is not affiliated with or endorsed by Activision. Call of Duty and related names belong to their respective owners.</p></div><div class="card"><h3>Build</h3><p>Version 3.9.0 · MB-SNDC-2026-0823-046</p><p>Copyright © 2026 Michael Barnes. All Rights Reserved.</p></div>`;bindGo();window.scrollTo(0,0)}
function render(){const parts=route().split('/'),root=parts[0],a=parts[1],b=parts[2];if(root==='home')renderHome();else if(root==='round-read')renderSideline();else if(root==='guided'&&!a)renderGuidedStart();else if(root==='guided'&&a==='q')renderGuidedQuestion(b||'start');else if(root==='guided'&&a==='result')renderGuidedResult(b);else if(root==='quick'&&!a)renderQuickList();else if(root==='quick')renderQuick(a);else if(root==='learn')renderLearn();else if(root==='lesson')renderLesson(a);else if(root==='armory'&&a==='role')renderArmoryDeep(b);else if(root==='armory')renderArmoryDeep();else if(root==='weapon')renderWeaponDeep(a);else if(root==='fights')renderFights();else if(root==='fight')renderFight(a);else if(root==='manual')renderManual();else if(root==='operation')renderOperation(a);else if(root==='practice')renderPractice();else if(root==='terms')renderTerms();else if(root==='term')renderTerm(a);else if(root==='notes')renderNotes();else if(root==='library')renderLibrary();else if(root==='about')renderAbout();else go('home');enhanceDetailPage();focusView()}
document.querySelectorAll('.nav').forEach(b=>b.onclick=()=>go(b.dataset.root));document.getElementById('aboutBtn').onclick=()=>go('about');document.getElementById('searchBtn').onclick=()=>go('library');window.addEventListener('hashchange',render);
window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();deferredInstall=e;const b=document.getElementById('installBtn');b.hidden=false;b.onclick=async()=>{await deferredInstall.prompt();deferredInstall=null;b.hidden=true}});
if('serviceWorker'in navigator){window.addEventListener('load',async()=>{const reg=await navigator.serviceWorker.register('./sw.js');const updateBtn=document.getElementById('updateBtn');const offer=w=>{waitingWorker=w;updateBtn.hidden=false;updateBtn.onclick=()=>{reloadForUpdate=true;updateBtn.disabled=true;updateBtn.textContent='Updating…';waitingWorker.postMessage({type:'SKIP_WAITING'})}};if(reg.waiting)offer(reg.waiting);reg.addEventListener('updatefound',()=>{const w=reg.installing;w.addEventListener('statechange',()=>{if(w.state==='installed'&&navigator.serviceWorker.controller)offer(w)})});navigator.serviceWorker.addEventListener('controllerchange',()=>{if(reloadForUpdate)location.reload()})})}
if(!location.hash)location.hash='#/home';else render();
